import{_ as a,o as n,c as s,a3 as t}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"工具与 MCP","description":"从 tool() 与 ToolMessage 生命周期到 Runtime Context 与 MCP 集成，建立 LangChain.js 工具能力地图。","frontmatter":{"title":"工具与 MCP","description":"从 tool() 与 ToolMessage 生命周期到 Runtime Context 与 MCP 集成，建立 LangChain.js 工具能力地图。"},"headers":[],"relativePath":"ts-ai/agent/tools-mcp/index.md","filePath":"ts-ai/agent/tools-mcp/index.md","lastUpdated":1786166505000}'),o={name:"ts-ai/agent/tools-mcp/index.md"};function l(c,e,d,i,r,p){return n(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="工具与-mcp" tabindex="-1">工具与 MCP <a class="header-anchor" href="#工具与-mcp" aria-label="Permalink to &quot;工具与 MCP&quot;">​</a></h1><blockquote><p>作者：cursor-grok-4.5</p></blockquote><p>工具把模型的结构化动作连接到应用与外部系统；MCP 把连接方式标准化到进程与服务边界。本分组始终区分四阶段：<strong>模型请求 → Schema 校验 → 受权执行 → ToolMessage 回灌</strong>。</p><h2 id="_1-学习目标" tabindex="-1">1. 学习目标 <a class="header-anchor" href="#_1-学习目标" aria-label="Permalink to &quot;1. 学习目标&quot;">​</a></h2><p>读完全组后，你应能：</p><ol><li>用 <code>tool()</code> + Zod 设计 <code>snake_case</code> 工具契约，并注册到 <code>bindTools</code> / <code>createAgent</code>；</li><li>手动追踪 <code>AIMessage.tool_calls</code> → 执行 → <code>ToolMessage.tool_call_id</code> 对齐的完整结果流；</li><li>分类工具错误、控制超时与返回体积，避免 stack 与 PII 进入模型上下文；</li><li>用 <code>contextSchema</code> 与 <code>config.context</code> 注入 <code>userId</code>、租户与权限，禁止模型自填身份；</li><li>说明 MCP Host / Client / Server 职责，并用 TS SDK 或适配器接入 Agent。</li></ol><h2 id="_2-文章顺序" tabindex="-1">2. 文章顺序 <a class="header-anchor" href="#_2-文章顺序" aria-label="Permalink to &quot;2. 文章顺序&quot;">​</a></h2><ol><li><a href="/ts-ai/agent/tools-mcp/tools-schemas">Tool 与 Schema</a>：<code>tool()</code>、<code>name</code> / <code>description</code> / Zod、返回值、<code>bindTools</code> 与 <code>createAgent</code>。</li><li><a href="/ts-ai/agent/tools-mcp/tool-call-tool-message">Tool Call 与 ToolMessage</a>：一次调用结果流、<code>tool_calls</code>、并行回灌、与 Agent 循环边界。</li><li><a href="/ts-ai/agent/tools-mcp/tool-errors-timeouts-results">工具错误、超时与结果转换</a>：错误 envelope、超时取消、脱敏与幂等。</li><li><a href="/ts-ai/agent/tools-mcp/runtime-context-injection">Runtime Context 可信注入</a>：<code>context</code> vs <code>messages</code> vs <code>thread_id</code>、<code>contextSchema</code>、信任边界。</li><li><a href="/ts-ai/agent/tools-mcp/mcp-typescript-sdk">MCP 与 TypeScript SDK</a>：协议角色、SDK 发现与调用、与本地工具对比。</li><li><a href="/ts-ai/agent/tools-mcp/langchain-mcp-integration">LangChain.js 集成 MCP</a>：<code>@langchain/mcp-adapters</code>、<code>MultiServerMCPClient</code>、错误与观测。</li></ol><h2 id="_3-知识地图" tabindex="-1">3. 知识地图 <a class="header-anchor" href="#_3-知识地图" aria-label="Permalink to &quot;3. 知识地图&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                    ┌─────────────────┐</span></span>
<span class="line"><span>                    │  ChatModel      │</span></span>
<span class="line"><span>                    │  bindTools      │</span></span>
<span class="line"><span>                    └────────┬────────┘</span></span>
<span class="line"><span>                             │ AIMessage.tool_calls</span></span>
<span class="line"><span>                             ▼</span></span>
<span class="line"><span>┌──────────────┐    ┌─────────────────┐    ┌──────────────┐</span></span>
<span class="line"><span>│ contextSchema│───▶│  tool() 执行    │───▶│ ToolMessage  │</span></span>
<span class="line"><span>│ config.context    │  校验·授权·超时  │    │ tool_call_id │</span></span>
<span class="line"><span>└──────────────┘    └────────┬────────┘    └──────┬───────┘</span></span>
<span class="line"><span>                             │                     │</span></span>
<span class="line"><span>                    本地实现 │                     │ 回灌 messages</span></span>
<span class="line"><span>                             │                     ▼</span></span>
<span class="line"><span>                    ┌────────▼────────┐    ┌─────────────────┐</span></span>
<span class="line"><span>                    │  MCP Server     │◀───│ mcp-adapters    │</span></span>
<span class="line"><span>                    │  (可选远程)     │    │ getTools()      │</span></span>
<span class="line"><span>                    └─────────────────┘    └─────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br></div></div><table tabindex="0"><thead><tr><th>主题</th><th>核心 API / 包</th></tr></thead><tbody><tr><td>工具定义</td><td><code>tool()</code> from <code>langchain</code>，Zod <code>schema</code></td></tr><tr><td>模型绑定</td><td><code>model.bindTools()</code>，<code>createAgent({ tools })</code></td></tr><tr><td>消息协议</td><td><code>AIMessage.tool_calls</code>，<code>ToolMessage</code>（字段见 <a href="/ts-ai/agent/langchain-core/messages-prompt-template">Message 与 Prompt 家族</a>）</td></tr><tr><td>可信身份</td><td><code>contextSchema</code>，<code>invoke(..., { context })</code>，<code>config.context</code></td></tr><tr><td>MCP</td><td><code>@modelcontextprotocol/sdk</code>，<code>@langchain/mcp-adapters</code></td></tr></tbody></table><h2 id="_4-与-langchain-核心-runtime-的边界" tabindex="-1">4. 与 LangChain 核心 / Runtime 的边界 <a class="header-anchor" href="#_4-与-langchain-核心-runtime-的边界" aria-label="Permalink to &quot;4. 与 LangChain 核心 / Runtime 的边界&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th>本组负责</th><th>不负责</th></tr></thead><tbody><tr><td><a href="/ts-ai/agent/langchain-core/">LangChain 核心</a></td><td>指向 Message 字段形状</td><td>Runnable 组合细节</td></tr><tr><td><strong>工具与 MCP（本组）</strong></td><td>Tool 契约、Tool Call 生命周期、Context 注入、MCP 接入</td><td>Agent 图结构、检查点实现</td></tr><tr><td><a href="/ts-ai/agent/runtime/">Agent Runtime</a></td><td>点到 <code>createAgent</code> 循环、Middleware 钩子</td><td>不重复 Middleware / 流式全文</td></tr><tr><td><a href="/ts-ai/agent/models-output/">模型与输出</a></td><td>不展开采样与结构化输出</td><td>—</td></tr></tbody></table><p>建议路径：完成 <a href="/ts-ai/agent/langchain-core/">LangChain 核心</a> 后进入本组，再读 <a href="/ts-ai/agent/runtime/create-agent">Agent Runtime</a>。</p><h2 id="_5-分组边界" tabindex="-1">5. 分组边界 <a class="header-anchor" href="#_5-分组边界" aria-label="Permalink to &quot;5. 分组边界&quot;">​</a></h2><ul><li>MCP ≠ 自动安全；Server 与 Host 仍需鉴权与最小工具集。</li><li>本组不包含：MCP 企业网关市场、工具审批 UI 组件百科。Nest 侧受控接入的全栈验收参考 <a href="/ts-ai/architecture/ai-customer-support/">实战 · AI 客服中心</a> 的 Gateway 边界门禁；MCP 治理落产品由 P4 经营数据分析项目实战承接（正文待写）；SSE 协议见全栈集成。</li><li>示例采用薄业务（订单 <code>get_order</code>、工单 <code>lookup_ticket</code>），便于对照轨迹调试。</li></ul><h2 id="_6-检查清单" tabindex="-1">6. 检查清单 <a class="header-anchor" href="#_6-检查清单" aria-label="Permalink to &quot;6. 检查清单&quot;">​</a></h2><ul><li>[ ] 工具名 <code>snake_case</code>，Schema 字段带 <code>.describe()</code></li><li>[ ] 每条 <code>tool_call_id</code> 有且仅有一条对应 <code>ToolMessage</code></li><li>[ ] 错误返回结构化 <code>{ ok, code, message }</code>，无 stack / PII</li><li>[ ] <code>userId</code> / <code>tenantId</code> 仅来自 <code>context</code>，不在工具参数中</li><li>[ ] MCP 集成处理 <code>ToolException</code> 与连接失败策略</li></ul><p>下一篇：<a href="/ts-ai/agent/tools-mcp/tools-schemas">Tool 与 Schema</a>。</p>`,19)])])}const g=a(o,[["render",l]]);export{m as __pageData,g as default};
